// 1. An id for the request, so every later log line and error can carry it.
app.use(requestId());
// 2. One structured log line per request, with that id. Health probes stay out of the logs.
app.use(
  pinoHttp({
    logger: deps.logger,
    genReqId: (req) => (req as Request).requestId,
    autoLogging: { ignore: (req) => req.url === "/healthz" || req.url === "/readyz" },
    customLogLevel: (_req, res, err) => (err !== undefined || res.statusCode >= 500 ? "warn" : "info"),
  }),
);
// ...
// 3. Security headers on everything, pages and API alike.
app.use(helmet(helmetOptions(config)));
// ...
// 5. JSON bodies, at most 100 kB: anything bigger is refused before it is read into memory.
app.use(express.json({ limit: "100kb" }));

// 6. Routes. Health and the OpenAPI document first, then the API, then the HTML pages.
app.use(healthRoutes({ readiness: deps.readiness, checkDatabase: deps.checkDatabase }));
// ...
app.use("/v1", cors(corsOptions(config)), apiLimiter(config.apiRateLimitPerMinute));
app.use("/v1", authRoutes({ controller: new AuthController(services.auth), auth, authLimiter: authLimiter() }));
app.use("/v1/me/favorites", favoritesRoutes({ favorites: services.favorites, auth }));
app.use("/v1/venues", venuesRoutes({ controller: new VenuesController(services.venues), auth }));
app.use("/v1/events/:eventId/ticket-types", ticketTypesRoutes({ controller: new TicketTypesController(services.ticketTypes), auth }));
app.use("/v1/events", eventsRoutes({ controller: new EventsController(services.events, loadCalendar()), auth }));
app.use("/v1/orders", ordersRoutes({ controller: new OrdersController(services.checkout, services.orders), auth }));
app.use("/v1/organizer", statsRoutes({ stats: services.stats, auth }));
app.use(pagesRoutes({ controller: new PagesController(services.events, services.ticketTypes) }));

// 7. Last: anything no route answered, then every error any layer threw.
app.use(notFound);
app.use(errorHandler);
return app;

const { services, tokens, posters } = createServices({ db: database.db, repositories: pgRepositories, config, logger });
const readiness = new Readiness();
const app = createApp({
  config,
  logger,
  services,
  tokens,
  posters,
  readiness,
  checkDatabase: () => ping(database.pool, 1_000),
  queries: database.queries,
});

const server = app.listen(config.port, config.host, (err) => {
  if (err !== undefined) {
    logger.fatal({ err }, `could not listen on port ${config.port}`);
    process.exit(1);
  }
  const address = server.address();
  const port = typeof address === "object" && address !== null ? address.port : config.port;
  logger.info({ config }, `Listening on http://localhost:${port}`);
});

export function eventsRoutes({ controller, auth }: { controller: EventsController; auth: AuthGuards }): Router {
  const router = Router();
  const organizer = [auth.required, requireRole("organizer", "admin")];
  const byId = validate({ params: EventIdParams });

  router.get("/", cacheControl("public, max-age=60"), validate({ query: ListEventsQuery }), controller.list);
  router.post("/", ...organizer, validate({ body: CreateEvent }), controller.create);
  router.get("/:eventId", auth.optional, cacheControl("public, max-age=60"), byId, controller.get);
  router.patch("/:eventId", ...organizer, validate({ params: EventIdParams, body: UpdateEvent }), controller.update);
  router.delete("/:eventId", ...organizer, byId, controller.remove);
  router.post("/:eventId/publish", ...organizer, byId, controller.publish);
  router.post("/:eventId/cancel", ...organizer, byId, controller.cancel);
  // Authentication runs before multer, so anonymous uploads are refused before any bytes are buffered.
  router.put("/:eventId/poster", ...organizer, byId, posterUpload, controller.uploadPoster);
  router.get("/:eventId/calendar.ics", byId, controller.calendar);
  return router;
}

export function ordersRoutes({ controller, auth }: { controller: OrdersController; auth: AuthGuards }): Router {
  const router = Router();
  router.use(auth.required, noStore);
  router.post("/", requireRole("customer"), requireIdempotencyKey, validate({ body: Checkout }), controller.checkout);
  router.get("/", validate({ query: ListOrdersQuery }), controller.list);
  router.get("/:orderId", validate({ params: OrderIdParams }), controller.get);
  router.post("/:orderId/cancel", validate({ params: OrderIdParams }), controller.cancel);
  return router;
}

export class EventsController {
  readonly #events: EventsService;
  readonly #calendar: Calendar;

  constructor(events: EventsService, calendar: Calendar) {
    this.#events = events;
    this.#calendar = calendar;
  }

  list: RequestHandler = async (_req, res) => {
    const page = await this.#events.list(res.locals.query as ListEventsQuery);
    res.json({ data: page.data.map(toEventSummaryJson), nextCursor: page.nextCursor });
  };

  get: RequestHandler = async (req, res) => {
    const { eventId } = res.locals.params as EventIdParams;
    const event = await this.#events.get(req.user, eventId);
    // The answer depends on who asks (drafts are visible to their owner), so caches must key on it.
    res.vary("Authorization");
    if (event.status === "draft") res.set("Cache-Control", "private, no-store");
    res.json(toEventJson(event));
  };

  create: RequestHandler = async (req, res) => {
    const event = await this.#events.create(currentUser(req), req.body as CreateEvent);
    res.status(201).location(`/v1/events/${event.id}`).json(toEventJson(event));
  };
  // ...
}
